import React, { useState } from 'react';
import { Box, Typography, Button, TextField, InputAdornment, IconButton, Paper } from '@mui/material';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import Dashboard from './Dashboard';
// import Sidebar from './Sidebar';

export default function App() {
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ brand: '', email: '', password: '' });
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleClickShowPassword = () => setShowPassword((show) => !show);

  const handleLogin = () => setIsLoggedIn(true);

  // Google Client ID ko yahan set karein (Google Cloud Console se copy karein)
 const clientId = "799486090464-09m7dt9julg1ubivpg2sf9v5qcvt5l.apps.googleusercontent.com";

  if (!isLoggedIn) {
    return (
      <Box
        sx={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          bgcolor: 'linear-gradient(90deg, #eafff0 0%, #00e676 100%)',
          background: 'linear-gradient(90deg, #eafff0 0%, #00e676 100%)',
        }}
      >
        <Paper
          elevation={6}
          sx={{
            display: 'flex',
            width: { xs: '95vw', md: 900 },
            minHeight: 500,
            borderRadius: 4,
            overflow: 'hidden',
          }}
        >
          {/* Right Side - Signup Form (now first) */}
          <Box
            sx={{
              flex: 1.2,
              bgcolor: '#fff',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              p: 4,
            }}
          >
            <Typography variant="h6" color="#00b050" fontWeight={700} mb={1} align="center">
              Get Started with
            </Typography>
            <Typography variant="h3" fontWeight={900} mb={2} align="center" sx={{ color: '#00b050', letterSpacing: 1 }}>
              Hub<span style={{ color: '#111' }}>Box</span>
            </Typography>
            <Typography variant="subtitle1" color="text.secondary" mb={1} align="center">
              Your videos, your stats, your world.
            </Typography>
            <Typography variant="h5" fontWeight={700} mb={2} align="center">
              Sign Up for Free
            </Typography>
            <TextField
              label="Channel or Business Name"
              name="brand"
              value={form.brand}
              onChange={handleChange}
              fullWidth
              sx={{ mb: 2 }}
            />
            <TextField
              label="Email Address"
              name="email"
              value={form.email}
              onChange={handleChange}
              fullWidth
              sx={{ mb: 2 }}
            />
            <TextField
              label="Create Password"
              name="password"
              type={showPassword ? 'text' : 'password'}
              value={form.password}
              onChange={handleChange}
              fullWidth
              sx={{ mb: 2 }}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton onClick={handleClickShowPassword} edge="end">
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
            <Button
              variant="contained"
              fullWidth
              sx={{
                mt: 1,
                bgcolor: '#00b050',
                color: '#fff',
                fontWeight: 700,
                borderRadius: 2,
                py: 1.2,
                fontSize: 18,
                boxShadow: '0 2px 12px #00b05044',
                '&:hover': { bgcolor: '#00913a' },
              }}
              onClick={handleLogin}
            >
              Create My Account
            </Button>
            {/* Google Login Button yahan add kar rahe hain */}
            {/* <GoogleLogin
              clientId={clientId}
              buttonText="Sign in with Google"
              onSuccess={async (response) => {
                // Backend ko token bhejein
                const res = await fetch('http://localhost:5000/api/auth/google-login', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ tokenId: response.tokenId }),
                });
                if (res.ok) setIsLoggedIn(true);
                else alert('Google login failed');
              }}
              onFailure={() => alert('Google login failed')}
              cookiePolicy={'single_host_origin'}
              style={{ width: '100%', marginTop: 16, borderRadius: 8 }}
            /> */}
            <Typography variant="body2" color="text.secondary" align="center" mt={2}>
              By continuing, you accept our <span style={{ color: '#00b050', fontWeight: 600 }}>User Policy</span> and <span style={{ color: '#00b050', fontWeight: 600 }}>Privacy Terms</span>.
            </Typography>
          </Box>
          {/* Left Side - Login Info (now second) */}
          <Box
            sx={{
              flex: 1,
              bgcolor: 'linear-gradient(135deg, #00e676 0%, #b2ffec 100%)',
              background: 'linear-gradient(135deg, #00e676 0%, #b2ffec 100%)',
              color: '#fff',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              p: 4,
            }}
          >
            <Typography variant="h5" fontWeight={700} mb={2} align="center">
              Already have an account?
            </Typography>
            <Typography variant="body1" mb={3} align="center">
              Log in to access your dashboard, manage your uploads, and track your growth.
            </Typography>
            <Button variant="outlined" sx={{ color: '#fff', borderColor: '#00b050', fontWeight: 600, borderRadius: 2, px: 4, '&:hover': { bgcolor: '#00b050', borderColor: '#00b050', color: '#fff' } }} onClick={handleLogin}>
              Go to Login
            </Button>
          </Box>
        </Paper>
      </Box>
    );
  }

  return <Dashboard />;
}
